/**
 * Shared TypeScript types for Seen Hijabi.
 *
 * These are application-level types used across client and server code.
 * Database entity types are generated by Prisma and imported from
 * `@/generated/prisma` (available after `prisma generate`).
 */

// ─── Order Source ─────────────────────────────────────────────────────────────

export type OrderSource =
  | "website"
  | "instagram"
  | "tiktok"
  | "whatsapp"
  | "facebook"
  | "direct"
  | "other";

// ─── Order Status ─────────────────────────────────────────────────────────────

export type OrderStatus =
  | "pending"
  | "confirmed"
  | "processing"
  | "shipped"
  | "delivered"
  | "cancelled";

// ─── Product / Storefront Types ───────────────────────────────────────────────

export interface ProductColor {
  id: string;
  name: string;
  hexCode: string;
}

export interface ProductSize {
  id: string;
  name: string;
  displayOrder: number;
}

export interface ProductVariant {
  id: string;
  colorId: string;
  sizeId: string;
  sku: string | null;
  stock: number;
  colorName: string;
  colorHex: string;
  sizeName: string;
}

export interface ProductImage {
  id: string;
  url: string;
  altText: string | null;
  displayOrder: number;
}

/** Lightweight product representation used in cards and lists */
export interface ProductCard {
  id: string;
  name: string;
  slug: string;
  price: number;
  discountPercent: number | null;
  discountedPrice: number | null;
  isFeatured: boolean;
  isNewArrival: boolean;
  isBestSeller: boolean;
  isActive: boolean;
  primaryImage: string | null;
  colors: Pick<ProductColor, "name" | "hexCode">[];
  isSoldOut: boolean;
}

/** Full product detail used on the product page */
export interface ProductDetail extends ProductCard {
  description: string | null;
  categoryId: string | null;
  categoryName: string | null;
  images: ProductImage[];
  variants: ProductVariant[];
}

// ─── Store Settings ───────────────────────────────────────────────────────────

export interface StoreSettings {
  storeName: string;
  logoUrl: string | null;
  whatsappNumber: string;
  instagramUrl: string | null;
  tiktokUrl: string | null;
  facebookUrl: string | null;
  currency: string;
  announcementText: string | null;
  announcementEnabled: boolean;
}

export interface ShippingSettings {
  freeShippingEnabled: boolean;
  freeShippingMinAmount: number | null;
  freeShippingMinQty: number | null;
  fixedShippingCost: number;
}

// ─── Checkout ─────────────────────────────────────────────────────────────────

export interface CheckoutFormData {
  fullName: string;
  phone: string;
  whatsapp?: string;
  governorate: string;
  city: string;
  address: string;
  notes?: string;
}

export interface CheckoutCartItem {
  variantId: string;
  quantity: number;
}

// ─── API Responses ────────────────────────────────────────────────────────────

export interface ApiResponse<T = void> {
  success: boolean;
  data?: T;
  error?: string;
}

